  TextBox Field(){return new TextBox{Dock=DockStyle.Fill,Margin=new Padding(3,3,7,3)};}
  Label Caption(string value){return new Label{Text=value,Dock=DockStyle.Fill,ForeColor=muted,Font=new Font("Segoe UI",9),TextAlign=ContentAlignment.BottomLeft,AutoEllipsis=true};}
  Button Btn(string value,bool primary,int width=0){var b=new Button{Text=value,Height=36,Dock=width==0?DockStyle.Fill:DockStyle.None,Width=width==0?120:width,Margin=new Padding(3,2,5,4),FlatStyle=FlatStyle.Flat,BackColor=primary?green:Color.White,ForeColor=primary?Color.White:ink,Cursor=Cursors.Hand};b.FlatAppearance.BorderColor=primary?green:Color.FromArgb(203,214,225);return b;}
  void AddColumn(string property,string text,int weight){grid.Columns.Add(new DataGridViewTextBoxColumn{DataPropertyName=property,HeaderText=text,FillWeight=weight,MinimumWidth=45,SortMode=DataGridViewColumnSortMode.NotSortable});}
  int Env{get{return environment.SelectedIndex==1?2:1;}}
  XmlLibrary Library(){return new XmlLibrary(output.Text,cnpj.Text,Env);}
  void LoadCertificate(object sender,EventArgs e){try{if(pfx.Text=="")throw new InvalidOperationException("Escolha o arquivo .pfx ou .p12.");var next=new CertificateSession(pfx.Text,password.Text);if(certificate!=null)certificate.Dispose();certificate=next;cnpj.Text=next.Cnpj;certStatus.Text="A1 carregado • CNPJ "+next.Cnpj+" • válido até "+next.Certificate.NotAfter.ToString("dd/MM/yyyy");certStatus.ForeColor=green;RefreshLibrary();SaveSettings();Log("Certificado A1 carregado. A senha foi removida do campo.");}catch(Exception ex){Error(ex);}finally{password.Clear();}}
  void Log(string value){if(IsDisposed)return;if(InvokeRequired){BeginInvoke(new Action<string>(Log),value);return;}journal.AppendText(DateTime.Now.ToString("HH:mm:ss")+"  "+value+System.Environment.NewLine);if(journal.TextLength>40000)journal.Text=journal.Text.Substring(journal.TextLength-25000);journal.SelectionStart=journal.TextLength;journal.ScrollToCaret();}
  void Error(Exception ex){Log(ex.Message);MessageBox.Show(this,ex.Message,"XML A1",MessageBoxButtons.OK,MessageBoxIcon.Information);}
  void SetBusy(bool value){busy=value;settings.Enabled=!value&&!demo;foreach(var b in new[]{search,byKey,import,science,export})b.Enabled=!value;search.Enabled=!value&&!demo;science.Enabled=!value&&!demo;cancel.Enabled=value;progress.Visible=value;}
  void RefreshLibrary(){if(cnpj==null||tabs==null||cnpj.Text.Trim()=="")return;try{var lib=Library();loadingScience=true;try{autoScience.Checked=sciences.Load(lib.Cnpj,lib.Environment).Enabled;}finally{loadingScience=false;}docs=lib.List();var s=states.Load(lib.Cnpj,lib.Environment);nsu.Text=s.Last;nsu.ReadOnly=s.Initialized;cursor.Text="NSU "+s.Last+(s.DistAfter>DateTime.UtcNow?" • próxima "+s.DistAfter.ToLocalTime().ToString("HH:mm"):"");ApplyFilter();}catch(Exception ex){loadingScience=true;autoScience.Checked=false;loadingScience=false;Log(ex.Message);}}
  void ScienceOptionChanged(object sender,EventArgs e){if(loadingScience||demo)return;try{var lib=Library();if(autoScience.Checked){if(certificate==null)throw new InvalidOperationException("Carregue o certificado A1 antes de ativar a ciência automática.");certificate.Validate(lib.Cnpj);if(uf.SelectedIndex==0)throw new InvalidOperationException("Selecione a UF da empresa.");if(MessageBox.Show(this,"Ativar Ciência da Operação automática?\n\nCNPJ: "+lib.Cnpj+"\nAmbiente: "+environment.Text+"\n\nO programa enviará o evento fiscal 210210, assinado com seu A1, para os resumos elegíveis já salvos e os recebidos nas próximas buscas. Depois, consultará as chaves para baixar o XML completo.\n\nCiência registra conhecimento da nota. Confira as notas e faça a manifestação conclusiva aplicável. O programa não a envia automaticamente.\n\nA automação funcionará enquanto o aplicativo estiver aberto com o A1 carregado. Autoriza ativar para esta empresa?","Ciência automática",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes){loadingScience=true;autoScience.Checked=false;loadingScience=false;return;}}sciences.Enable(lib.Cnpj,lib.Environment,autoScience.Checked);Log("Ciência automática "+(autoScience.Checked?"ativada":"desativada")+" para "+lib.Cnpj+" / "+environment.Text+".");}catch(Exception ex){loadingScience=true;autoScience.Checked=false;loadingScience=false;Error(ex);}}
  AutoScienceRunner ScienceRunner(XmlLibrary lib,ISefaz client){return new AutoScienceRunner(states,sciences,queues,lib,client,Log);}
  int UfCode{get{return uf.SelectedIndex>0?int.Parse(uf.Text.Substring(3)):0;}}
  void FinishWork(){if(work!=null){if(work.IsCancellationRequested)try{var lib=Library();sciences.Enable(lib.Cnpj,lib.Environment,false);using(queues.Lock(lib.Cnpj,lib.Environment)){var q=queues.Load(lib.Cnpj,lib.Environment);q.AutoContinue=false;queues.Save(lib.Cnpj,lib.Environment,q);}Log("Automação pausada. Histórico e pendentes preservados.");}catch(Exception ex){Log(ex.Message);}work.Dispose();work=null;}SetBusy(false);RefreshLibrary();}
  async Task RunAutomaticConfirmations(){if(busy||demo)return;try{var lib=Library();certificate.Validate(lib.Cnpj);SetBusy(true);work=new CancellationTokenSource();int count=await Task.Run(()=>new AutoConfirmationRunner(states,confirmations,queues,lib,new SefazClient(certificate.Certificate),Log).Run(work.Token));if(count>0)Log(count+" confirmação(ões) processada(s). A fila consultará os XMLs completos após a disponibilização.");}catch(OperationCanceledException){Log("Confirmações interrompidas; histórico preservado.");}catch(Exception ex){Log("Confirmações pausadas: "+ex.Message);}finally{FinishWork();}}
  async Task RunAutomaticScience(){if(busy||demo)return;try{var lib=Library();certificate.Validate(lib.Cnpj);var s=sciences.Load(lib.Cnpj,lib.Environment);bool send=s.Enabled&&s.Next<=DateTime.UtcNow&&states.Load(lib.Cnpj,lib.Environment).AllAfter<=DateTime.UtcNow;bool recover=s.Records.Any(r=>r.Code=="596"&&!r.Queued);if(!send&&!recover)return;int code=UfCode;if(code==0)return;SetBusy(true);work=new CancellationTokenSource();int count=await Task.Run(()=>{var runner=ScienceRunner(lib,new SefazClient(certificate.Certificate));int recovered=runner.ScheduleDownloads(code,work.Token);if(recovered>0)Log(recovered+" chave(s) do histórico agendada(s) para consultar XML, sem novo evento.");return send?runner.Run(code,work.Token):0;});if(count>0)Log(count+" ciência(s) processada(s). XMLs agendados na fila de chaves.");}catch(OperationCanceledException){Log("Ciência automática interrompida.");}catch(Exception ex){try{var lib=Library();sciences.Enable(lib.Cnpj,lib.Environment,false);}catch{}Log("Ciência automática pausada: "+ex.Message);}finally{FinishWork();}}
  void ApplyFilter(){if(tabs==null||grid==null)return;string cat=tabs.SelectedTab==null?"Recebidas":tabs.SelectedTab.Text;string q=filter==null?"":filter.Text.Trim();try{var visible=DocumentFilter.Apply(docs,cat,q,periodEnabled.Checked?(DateTime?)dateFrom.Value.Date:null,periodEnabled.Checked?(DateTime?)dateTo.Value.Date:null);grid.DataSource=visible;periodStatus.Text=periodEnabled.Checked?visible.Count+" documento(s) no período; filtro aplicado à exportação.":"Data de emissão; eventos usam a data do evento.";periodStatus.ForeColor=muted;}catch(InvalidOperationException ex){grid.DataSource=new List<DocItem>();periodStatus.Text=ex.Message;periodStatus.ForeColor=Color.FromArgb(160,65,25);}counts.Text=docs.Count(d=>d.Category=="Recebidas")+" recebidas   ·   "+docs.Count(d=>d.Category=="Emitidas")+" emitidas   ·   "+docs.Count(d=>d.Category=="Resumos")+" resumos   ·   "+docs.Count(d=>d.Category=="Eventos")+" eventos";}
  async Task ManageKeys(){if(busy)return;managingQueue=true;bool start=false;try{var lib=Library();int code=uf.SelectedIndex>0?int.Parse(uf.Text.Substring(3)):0;using(var d=new KeyBatchForm(queues,lib.Cnpj,lib.Environment,code))start=d.ShowDialog(this)==DialogResult.OK;}catch(Exception ex){Error(ex);}finally{managingQueue=false;}if(start&&!demo)await RunQueue(false);}
  void CompleteQueueScience(AutoScienceRunner runner,XmlLibrary lib,SefazClient client,int code,CancellationToken token){try{new AutoConfirmationRunner(states,confirmations,queues,lib,client,Log).Run(token);runner.RunForQueue(code,token);runner.Run(code,token);}catch(OperationCanceledException){throw;}catch(Exception ex){Log("Manifestação pausada: "+ex.Message+". A fila de download mantém suas pendentes.");}}
  async Task RunQueue(bool background){if(busy||demo)return;try{if(certificate==null)throw new InvalidOperationException("Carregue o A1 para iniciar ou continuar a fila.");var lib=Library();certificate.Validate(lib.Cnpj);SetBusy(true);work=new CancellationTokenSource();int code=UfCode;var result=await Task.Run(()=>{var client=new SefazClient(certificate.Certificate);var runner=ScienceRunner(lib,client);runner.ScheduleDownloads(code,work.Token);var batch=new KeyBatchRunner(states,queues,lib,client,Log).Run(work.Token);CompleteQueueScience(runner,lib,client,code,work.Token);var finalQueue=queues.Load(lib.Cnpj,lib.Environment);batch.Pending=finalQueue.Pending;batch.Next=finalQueue.Next;return batch;});Log(result.Message+" "+result.Processed+" consulta(s); "+result.Downloaded+" documento(s); "+result.Pending+" pendente(s)."+(result.Next>DateTime.UtcNow?" Próxima janela: "+result.Next.ToLocalTime().ToString("dd/MM HH:mm:ss"):""));}catch(Exception ex){try{var lib=Library();using(queues.Lock(lib.Cnpj,lib.Environment)){var q=queues.Load(lib.Cnpj,lib.Environment);q.AutoContinue=false;queues.Save(lib.Cnpj,lib.Environment,q);}}catch{}if(background)Log(ex.Message);else Error(ex);}finally{FinishWork();}}
  async Task Download(string key){if(busy||demo)return;try{if(certificate==null)throw new InvalidOperationException("Carregue o certificado A1 antes de consultar.");var lib=Library();certificate.Validate(lib.Cnpj);if(uf.SelectedIndex==0)throw new InvalidOperationException("Selecione a UF da empresa consultada.");int code=int.Parse(uf.Text.Substring(3));string initial=Rules.Nsu(nsu.Text);SaveSettings();SetBusy(true);work=new CancellationTokenSource();var client=new SefazClient(certificate.Certificate);int count=await Task.Run(()=>{var runner=ScienceRunner(lib,client);runner.ScheduleDownloads(code,work.Token);int downloaded=new Downloader(states,client,lib,Log).Run(code,initial,key,work.Token);runner.Run(code,work.Token);return downloaded;});Log("Busca concluída: "+count+" documento(s) processado(s). Arquivos em "+lib.Folder);}catch(OperationCanceledException){automatic.Checked=false;Log("Busca interrompida. O NSU dos lotes gravados foi preservado.");}catch(Exception ex){automatic.Checked=false;Error(ex);}finally{FinishWork();}}
  async Task Import(){if(busy)return;try{var lib=Library();using(var d=new OpenFileDialog{Filter="XML de NF-e (*.xml)|*.xml",Multiselect=true,Title="Importar XMLs recebidos ou emitidos pelo CNPJ"}){if(d.ShowDialog(this)!=DialogResult.OK)return;string[] files=d.FileNames;SetBusy(true);int count=await Task.Run(()=>{int ok=0;foreach(string f in files)try{if(new FileInfo(f).Length>20*1024*1024)throw new InvalidDataException("Arquivo acima de 20 MB.");lib.Store(File.ReadAllBytes(f),"",true);ok++;}catch(Exception ex){Log(Path.GetFileName(f)+": "+ex.Message);}return ok;});Log(count+" XML(s) importado(s). Os arquivos de origem foram preservados.");}}catch(Exception ex){Error(ex);}finally{SetBusy(false);RefreshLibrary();}}
  async Task RegisterScience(){if(busy||demo)return;try{if(certificate==null)throw new InvalidOperationException("Carregue o certificado A1.");var lib=Library();certificate.Validate(lib.Cnpj);var selected=grid.SelectedRows.Cast<DataGridViewRow>().Select(r=>r.DataBoundItem as DocItem).Where(x=>x!=null&&x.Category=="Resumos").ToList();if(selected.Count!=1)throw new InvalidOperationException("Selecione um único resumo na guia Resumos.");var item=selected[0];if(!Rules.Key(item.Key))throw new InvalidOperationException("Chave inválida.");if(MessageBox.Show(this,"Enviar Ciência da Operação para a NF-e\n"+item.Key+"?\n\nSerá enviado um evento fiscal assinado à SEFAZ. Após o registro, a chave será consultada automaticamente a cada hora, até 24 tentativas, enquanto o aplicativo estiver aberto com o A1 carregado.","Registrar ciência",MessageBoxButtons.YesNo,MessageBoxIcon.Question)!=DialogResult.Yes)return;SetBusy(true);work=new CancellationTokenSource();
    int code=UfCode;var result=await Task.Run(()=>ScienceRunner(lib,new SefazClient(certificate.Certificate)).Manual(item,code,work.Token));Log("Ciência "+result.Code+": "+result.Message+(result.CanCheckXml?". Confira a consulta do XML na fila de chaves; nenhum outro evento será enviado para esta chave.":". Confira o retorno em Manifestacoes."));
   }catch(OperationCanceledException){Log("Solicitação interrompida. Confira o retorno antes de enviar novamente.");}catch(Exception ex){Error(ex);}finally{FinishWork();}}
  void Export(object sender,EventArgs e){try{var items=grid.Rows.Cast<DataGridViewRow>().Select(r=>r.DataBoundItem as DocItem).Where(i=>i!=null).ToList();if(items.Count==0)throw new InvalidOperationException("Não há XMLs nesta guia para exportar.");using(var d=new SaveFileDialog{Filter="Arquivo ZIP (*.zip)|*.zip",FileName="XMLs_"+tabs.SelectedTab.Text+"_"+DateTime.Now.ToString("yyyyMMdd")+".zip"})if(d.ShowDialog(this)==DialogResult.OK){using(var f=new FileStream(d.FileName,FileMode.Create,FileAccess.Write))using(var zip=new ZipArchive(f,ZipArchiveMode.Create)){foreach(var item in items){var entry=zip.CreateEntry(Path.GetFileName(item.FilePath),CompressionLevel.Optimal);using(var input=File.OpenRead(item.FilePath))using(var outStream=entry.Open())input.CopyTo(outStream);}}Log(items.Count+" XML(s) exportado(s) para "+d.FileName);}}catch(Exception ex){Error(ex);}}
  string SettingsPath{get{return Path.Combine(System.Environment.GetFolderPath(System.Environment.SpecialFolder.LocalApplicationData),"XML-A1","preferencias.xml");}}
  void SaveSettings(){if(demo)return;try{var xml=new XDocument(new XElement("preferencias",new XElement("cnpj",cnpj.Text),new XElement("certificado",pfx.Text),new XElement("pasta",output.Text),new XElement("uf",uf.SelectedIndex),new XElement("ambiente",environment.SelectedIndex),new XElement("filtrarPeriodo",periodEnabled.Checked),new XElement("dataInicial",dateFrom.Value.Date.ToString("yyyy-MM-dd")),new XElement("dataFinal",dateTo.Value.Date.ToString("yyyy-MM-dd"))));Rules.WriteAtomic(SettingsPath,Rules.Utf8(xml));}catch(Exception ex){Log("Não foi possível salvar as preferências: "+ex.Message);}}
  void LoadSettings(){if(demo)return;try{if(!File.Exists(SettingsPath))return;var e=Rules.Xml(File.ReadAllBytes(SettingsPath)).Root;cnpj.Text=(string)e.Element("cnpj")??"";pfx.Text=(string)e.Element("certificado")??"";output.Text=(string)e.Element("pasta")??output.Text;int index;if(int.TryParse((string)e.Element("uf"),out index)&&index>=0&&index<uf.Items.Count)uf.SelectedIndex=index;if(int.TryParse((string)e.Element("ambiente"),out index)&&index>=0&&index<=1)environment.SelectedIndex=index;DateTime day;if(DateTime.TryParseExact((string)e.Element("dataInicial"),"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out day)&&day>=dateFrom.MinDate&&day<=dateFrom.MaxDate)dateFrom.Value=day;if(DateTime.TryParseExact((string)e.Element("dataFinal"),"yyyy-MM-dd",CultureInfo.InvariantCulture,DateTimeStyles.None,out day)&&day>=dateTo.MinDate&&day<=dateTo.MaxDate)dateTo.Value=day;periodEnabled.Checked=(bool?)e.Element("filtrarPeriodo")??false;}catch(Exception ex){Log("Preferências não carregadas: "+ex.Message);}}
  void LoadDemo(){cnpj.Text=SelfTests.SampleCnpj;output.Text=Path.Combine(Path.GetTempPath(),"XML-A1-Demo");var lib=Library();SelfTests.SeedDemo(lib);RefreshLibrary();certStatus.Text="Demonstração offline • dados sintéticos • nenhuma consulta à SEFAZ";Log("Modo de demonstração: funções de consulta e manifestação desativadas.");}
 }
